    if(kind.equals("DISPOSED")){if(!Objects.equals(inventory.current(c,"QuantitySegments",id(s,"sourceSegmentId")).get("placeId"),s.get("currentPlaceId")))throw held();var recovered=current.stream().filter(x->"RECOVERED".equals(x.get("kind"))).map(RecallPartition::range).toList();if(!QualityRanges.subtract(List.of(range),recovered).isEmpty())throw DomainError.invalid("Disposal requires previously recovered same physical subset");stock.dispose(c,sc.get("rootSegmentId").toString(),start,q,id(s,"sourceSegmentId"),at(fact.get("effectiveFrom")),occurrence);}
