 private void residual(DomainContext c,Map<String,Object>a,Map<String,Object>sc){var duty=responsibility.require("Assignments",c.organizationId(),a.get("residualDutyId").toString());if(!"OPEN".equals(duty.get("status"))||!Boolean.TRUE.equals(duty.get("valid"))||!"RECALL_EXCEPTION_RESIDUAL".equals(duty.get("kind"))||duty.get("nextAction")==null||duty.get("nextCheckAt")==null||!at(duty.get("nextCheckAt")).isAfter(clock.instant()))throw DomainError.invalid("Current exception residual responsibility required");for(String k:List.of("ownerId","supervisorId"))if(!"HUMAN".equals(identity.actor(c.organizationId(),duty.get(k).toString()).orElseThrow(DomainError::forbidden).get("kind")))throw DomainError.forbidden();}
 private Map<String,Object> payload(DomainContext c,Map<String,Object>fact){var refs=(List<?>)fact.get("evidenceRefs");var event=sources.require("Events",c.organizationId(),refs.get(3).toString());try{return new com.fasterxml.jackson.databind.ObjectMapper().readValue(event.get("payload").toString(),Map.class);}catch(Exception e){throw held();}}
 private Map<String,Object> approval(DomainContext c,Map<String,Object>sc,Map<String,Object>s,Map<String,List<String>> scopes){hash(sc,s);var a=r.current(c.organizationId(),"Approvals",id(s,"approvalId"));var approvals=r.rows(c,"Approvals").stream().filter(x->sc.get("ID").equals(x.get("scopeId"))).sorted(Comparator.comparingInt(x->n(x.get("revision")))).toList();if(approvals.isEmpty()||!a.get("ID").equals(approvals.getLast().get("ID"))||!"APPROVE".equals(a.get("decision"))||!Objects.equals(sc.get("scopeHash"),a.get("scopeHash"))||!Objects.equals(sc.get("version"),a.get("scopeVersion"))||!Objects.equals(sc.get("ID"),a.get("scopeId"))||!clock.instant().isBefore(at(a.get("validUntil"))))throw new DomainError("HELD","RECALL_APPROVAL_STALE","Current exact ADMIN recall approval required");if(!policies.rule(c,"approveRecall").policyHash().equals(a.get("policyHash")))throw new DomainError("HELD","APPROVAL_POLICY_CHANGED","Recall policy changed");admin(new DomainContext(c.organizationId(),a.get("approverId").toString(),c.stableRequestOwner(),c.asOf(),c.knownAt()),scopes);return a;}
 private void admin(DomainContext c,Map<String,List<String>> scopes){authorizeEvery(c,"approveRecall",scopes);if(!"HUMAN".equals(identity.actor(c.organizationId(),c.actorId()).orElseThrow(DomainError::forbidden).get("kind"))||!auth.permittedScopes(c,"approveRecall",scopes))throw DomainError.forbidden();if(identity.rows("ManagementAuthorities",c.organizationId()).stream().noneMatch(x->c.actorId().equals(x.get("actorId"))&&"approveRecall".equals(x.get("capabilityId"))&&active(x)&&("ORGANIZATION".equals(x.get("scopeKind"))&&c.organizationId().equals(x.get("scopeId"))||scopes.getOrDefault(x.get("scopeKind"),List.of()).contains(x.get("scopeId")))))throw DomainError.forbidden();}
 private void authorizeEvery(DomainContext c,String cap,Map<String,List<String>>scopes){for(var dimension:scopes.entrySet())for(String value:dimension.getValue()){var one=new LinkedHashMap<>(scopes);one.put(dimension.getKey(),List.of(value));auth.authorizeScopes(c,cap,one);}}
 private boolean active(Map<String,Object>x){Instant now=clock.instant();return x.get("validFrom")!=null&&x.get("validUntil")!=null&&!now.isBefore(at(x.get("validFrom")))&&now.isBefore(at(x.get("validUntil")))&&(x.get("revokedAt")==null||now.isBefore(at(x.get("revokedAt"))));}
 private static void hash(Map<String,Object>sc,Map<String,Object>s){if(!Objects.equals(sc.get("scopeHash"),text(s,"scopeHash")))throw new DomainError("HELD","APPROVAL_HASH_MISMATCH","Recall scope changed");}
 private static void bounds(Map<String,Object>sc,BigDecimal start,BigDecimal q){if(start.compareTo((BigDecimal)sc.get("startQuantity"))<0||start.add(q).compareTo(((BigDecimal)sc.get("startQuantity")).add((BigDecimal)sc.get("quantity")))>0)throw DomainError.invalid("Recovery exceeds approved recall physical range");}
